36	// The access lifecycle: a granted device reads exactly what the creator sees,
37	// a revoke returns it to 403 at once, and repeating an action is idempotent.
38	func TestAttachmentAccessGrantReadRevokeContract(t *testing.T) {
39		h, _ := newTestHandler(t)
40		registerDevice(t, h, "dev-1")
41		registerDevice(t, h, "dev-2")
42		content := []byte("hello world")
43		mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)
44		putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
45		putChunk(t, h, "dev-1", "att-1", 1, []byte("o wo"))
46		putChunk(t, h, "dev-1", "att-1", 2, []byte("rld"))
47		w, body := completeAttachment(t, h, "dev-1", "att-1")
48		if w.Code != http.StatusOK || body["complete"] != true {
49			t.Fatalf("complete = %d %v", w.Code, body)
50		}
51	
52		// Before any grant every other device is unauthorized: 403 on both reads.
53		if w := getAttachmentMeta(t, h, "dev-2", "att-1"); w.Code != http.StatusForbidden {
54			t.Fatalf("meta before grant = %d, want 403", w.Code)
55		}
56		if w := getChunk(t, h, "dev-2", "att-1", 0); w.Code != http.StatusForbidden {
57			t.Fatalf("chunk before grant = %d, want 403", w.Code)
58		}
59	
60		// The first grant is the first write; repeating it is idempotent.
61		w, body = setAccess(t, h, "dev-1", "att-1", "dev-2", "grant")
62		if w.Code != http.StatusOK || body["deviceId"] != "dev-2" ||
63			body["authorized"] != true || body["changed"] != true {
64			t.Fatalf("grant = %d %v body=%s", w.Code, body, w.Body.String())
65		}
66		w, body = setAccess(t, h, "dev-1", "att-1", "dev-2", "grant")
67		if w.Code != http.StatusOK || body["authorized"] != true || body["changed"] != false {
68			t.Fatalf("grant retry = %d %v", w.Code, body)
69		}
70	
71		// The granted device sees byte-for-byte what the creator sees.
72		creatorMeta := getAttachmentMeta(t, h, "dev-1", "att-1")
73		grantedMeta := getAttachmentMeta(t, h, "dev-2", "att-1")
74		if grantedMeta.Code != http.StatusOK || grantedMeta.Body.String() != creatorMeta.Body.String() {
75			t.Fatalf("granted meta = %d %q, creator %d %q",
76				grantedMeta.Code, grantedMeta.Body.String(), creatorMeta.Code, creatorMeta.Body.String())
77		}
78		for i := int64(0); i < 3; i++ {
79			creatorChunk := getChunk(t, h, "dev-1", "att-1", i)
80			grantedChunk := getChunk(t, h, "dev-2", "att-1", i)
81			if grantedChunk.Code != http.StatusOK || grantedChunk.Body.String() != creatorChunk.Body.String() {
82				t.Fatalf("granted chunk %d = %d %q, creator %d %q",
83					i, grantedChunk.Code, grantedChunk.Body.String(), creatorChunk.Code, creatorChunk.Body.String())
84			}
85		}
86	
87		// Revoke flips the state once; the granted device's reads are 403 again at
88		// once, while the creator keeps reading the sealed content unchanged.
89		w, body = setAccess(t, h, "dev-1", "att-1", "dev-2", "revoke")
90		if w.Code != http.StatusOK || body["authorized"] != false || body["changed"] != true {
91			t.Fatalf("revoke = %d %v", w.Code, body)
92		}
93		w, body = setAccess(t, h, "dev-1", "att-1", "dev-2", "revoke")
94		if w.Code != http.StatusOK || body["changed"] != false {
95			t.Fatalf("revoke retry = %d %v", w.Code, body)
96		}
97		if w := getAttachmentMeta(t, h, "dev-2", "att-1"); w.Code != http.StatusForbidden {
98			t.Fatalf("meta after revoke = %d, want 403", w.Code)
99		}
100		if w := getChunk(t, h, "dev-2", "att-1", 0); w.Code != http.StatusForbidden {
101			t.Fatalf("chunk after revoke = %d, want 403", w.Code)
102		}
103		if w := getChunk(t, h, "dev-1", "att-1", 0); w.Code != http.StatusOK || w.Body.String() != "hell" {
104			t.Fatalf("creator chunk after revoke = %d %q", w.Code, w.Body.String())
105		}
106	
107		// The revoke deleted nothing: the sealed content is still reused by digest.
108		mustCreateAttachment(t, h, "dev-2", "att-2", content, 4)
109		putChunk(t, h, "dev-2", "att-2", 0, []byte("hell"))
110		putChunk(t, h, "dev-2", "att-2", 1, []byte("o wo"))
111		putChunk(t, h, "dev-2", "att-2", 2, []byte("rld"))
112		w, body = completeAttachment(t, h, "dev-2", "att-2")
113		if w.Code != http.StatusOK || body["reused"] != true {
114			t.Fatalf("dedup after revoke = %d %v", w.Code, body)
115		}
116	}
